import sys

sys.stdout.reconfigure(newline="\n")


def to_base(value, base):
    digits = "0123456789abcdef"
    if value == 0:
        return "0"
    out = []
    while value:
        value, remainder = divmod(value, base)
        out.append(digits[remainder])
    return "".join(reversed(out))


def main():
    token = sys.stdin.read().strip()
    sign = ""
    body = token
    if body[:1] in ("+", "-"):
        sign = body[0]
        body = body[1:]
    lowered = body.lower()
    if lowered[:2] == "0b":
        value = int(body[2:], 2)
    elif lowered[:2] == "0o":
        value = int(body[2:], 8)
    elif lowered[:2] == "0x":
        value = int(body[2:], 16)
    else:
        value = int(body, 10)
    if sign == "-":
        value = -value
    out_sign = "-" if value < 0 else ""
    magnitude = abs(value)
    print("dec=%d" % value)
    print("bin=%s0b%s" % (out_sign, to_base(magnitude, 2)))
    print("oct=%s0o%s" % (out_sign, to_base(magnitude, 8)))
    print("hex=%s0x%s" % (out_sign, to_base(magnitude, 16)))


main()

import sys

