def canonical(token):
    index = 0
    negative = False
    if token[:1] in ("+", "-"):
        negative = token[0] == "-"
        index = 1
    digits = token[index:]
    if not digits:
        return None
    for ch in digits:
        if ch < "0" or ch > "9":
            return None
    value = int(digits)
    if value == 0:
        return "0"
    return ("-" if negative else "") + str(value)


def main():
    out = []
    for token in sys.stdin.read().split():
        result = canonical(token)
        out.append("ERR " + token if result is None else "OK " + result)
    if out:
        sys.stdout.write("\n".join(out) + "\n")


main()

import sys

