def to_symbolic(digits):
    flags = ("r", "w", "x")
    out = []
    for ch in digits:
        bits = int(ch)
        for index in range(3):
            out.append(flags[index] if bits & (4 >> index) else "-")
    return "".join(out)


def to_octal(symbolic):
    out = []
    for start in range(0, 9, 3):
        bits = 0
        for index in range(3):
            if symbolic[start + index] != "-":
                bits |= 4 >> index
        out.append(str(bits))
    return "".join(out)


def main():
    text = sys.stdin.read().strip()
    if len(text) == 3 and all("0" <= ch <= "7" for ch in text):
        print(to_symbolic(text))
    else:
        print(to_octal(text))


main()

import sys

sys.stdout.reconfigure(newline="\n")


def is_hex_digit(ch):
    return ("0" <= ch <= "9") or ("a" <= ch <= "f") or ("A" <= ch <= "F")


def escape(text):
    out = []
    for ch in text:
        if ch == "\\":
            out.append("\\\\")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif " " <= ch <= "~":
            out.append(ch)
        else:
            out.append("\\x%02x" % ord(ch))
    return "".join(out)


def unescape(text):
    out = []
    index = 0
    while index < len(text):
        ch = text[index]
        if ch != "\\" or index + 1 >= len(text):
            out.append(ch)
            index += 1
            continue
        nxt = text[index + 1]
        if nxt == "\\":
            out.append("\\")
            index += 2
        elif nxt == "t":
            out.append("\t")
            index += 2
        elif nxt == "n":
            out.append("\n")
            index += 2
        elif nxt == "r":
            out.append("\r")
            index += 2
        elif nxt == "x" and index + 3 < len(text) and is_hex_digit(text[index + 2]) and is_hex_digit(text[index + 3]):
            out.append(chr(int(text[index + 2:index + 4], 16)))
            index += 4
        else:
            out.append("\\")
            index += 1
    return "".join(out)


def main():
    rows = sys.stdin.read().split("\n")
    mode = rows[0].strip()
    payload = rows[1] if len(rows) > 1 else ""
    print(escape(payload) if mode == "esc" else unescape(payload))


main()

