def glob_match(pattern, text):
    p = 0
    t = 0
    star = -1
    mark = 0
    while t < len(text):
        if p < len(pattern) and (pattern[p] == "?" or pattern[p] == text[t]):
            p += 1
            t += 1
        elif p < len(pattern) and pattern[p] == "*":
            star = p
            mark = t
            p += 1
        elif star >= 0:
            p = star + 1
            mark += 1
            t = mark
        else:
            return False
    while p < len(pattern) and pattern[p] == "*":
        p += 1
    return p == len(pattern)


def main():
    rows = sys.stdin.read().split("\n")
    pattern = rows[0]
    text = rows[1] if len(rows) > 1 else ""
    print("MATCH" if glob_match(pattern, text) else "NO MATCH")


