def extension_of(path):
    basename = path.rsplit("/", 1)[-1]
    dot = basename.rfind(".")
    if dot <= 0 or dot == len(basename) - 1:
        return ""
    return basename[dot + 1:]


def main():
    groups = {}
    for line in sys.stdin.read().split("\n"):
        if line == "":
            continue
        groups.setdefault(extension_of(line), []).append(line)
    order = sorted(key for key in groups if key != "")
    if "" in groups:
        order.append("")
    for key in order:
        members = sorted(groups[key])
        print("ext=%s count=%d" % (key if key else "(none)", len(members)))
        for path in members:
            print(path)


